package app.space.notes.runtime;

import android.content.*;
import android.os.*;
import org.json.JSONObject;
import java.io.*;
import java.util.concurrent.*;

/** Opt-in, app-private, bounded diagnostic breadcrumbs. Never passes note/media/URI content. */
public final class Diagnostics {
 private static final Object LOCK=new Object();
 private static final ThreadPoolExecutor WRITER=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(256),r->{Thread t=new Thread(r,"notes-diagnostics");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static final ThreadPoolExecutor EXPORTER=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"notes-diagnostic-export");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static volatile Context app;private static volatile boolean enabled;private static long generation;private static boolean installed;
 private static final int LIMIT=512*1024;
 private static final java.util.Set<String> SAFE_CONTROLS=new java.util.HashSet<>(java.util.Arrays.asList("Image","Drawing","Save drawing","Remove image","Folders","Move to folder","Create folder","Background","Appearance","Diagnostics","Edit shape","Group","Undo diagram","Redo diagram","Edit arrows","Apply filters","Select all","Select none","+ Text","New text note","Library","Add to your note","Colour, labels & reminder","Note actions","Filter & view","+ Checklist","Filters","Hide filters","Undo","Settings","Back","Pin","Unpin","Capture tools","Organise tools","More actions","Text formatting","Share","Copy","Archive","Unarchive","Trash","Restore","Labels","Colour","Reminder","Clear reminder","Diagram","View diagram","Export PDF","Read image","Record voice","Voice inbox","Bold","Italic","Underline","Strike","Heading 1","Heading 2","Clear","+ Item","↑","↓","←","→","Indent","Outdent","Remove","Hide checked","Show checked","To text","Convert to checklist","Process","Decision","Start / End","Input / Output","Ellipse","Text box","Edit shape","Connect","Delete shape","Wider","Narrower","Taller","Shorter","Undo diagram","Back to note","Play","Stop playback","Export WAV","Retry transcript","Open note","Refresh","Stop and transcribe","Storage","Notes","Manage labels","Home widget","List view","Grid view","Sort: created","Sort: edited","All labels","All labels ✓","Storage & recovery","Offline models & licenses","Export diagnostics","Delete diagnostic logs","Choose folder","Open library","Retry save","Backups","Use device storage","Export backup","Import backup","Confirm merge","Cancel","Save labels","Done","Default","Red","Orange","Yellow","Green","Teal","Blue","Dark blue","Purple","Pink","Brown","Gray"));
 public static String controlName(CharSequence name){String value=name==null?"":name.toString();return SAFE_CONTROLS.contains(value)?value:"content-control";}
 private Diagnostics(){}
 public static void initialize(Context context){synchronized(LOCK){if(app!=context.getApplicationContext()){generation++;WRITER.getQueue().clear();}app=context.getApplicationContext();enabled=app.getSharedPreferences("notes-diagnostics",0).getBoolean("enabled",false);if(!installed){installed=true;Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{crash(error);if(previous!=null)previous.uncaughtException(thread,error);else{android.os.Process.killProcess(android.os.Process.myPid());System.exit(10);}});}}if(enabled)environment("session.start");}
 public static boolean enabled(){return enabled;}
 public static void setEnabled(boolean value){synchronized(LOCK){enabled=value;generation++;WRITER.getQueue().clear();app.getSharedPreferences("notes-diagnostics",0).edit().putBoolean("enabled",value).commit();}if(value)environment("collection.enabled");}
 public static void record(String event,String detail){if(!enabled || app==null)return;final long token; synchronized(LOCK){token=generation;}final long at=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();final String thread=Thread.currentThread().getName();try{WRITER.execute(()->{synchronized(LOCK){if(!enabled || token!=generation)return;try{JSONObject row=new JSONObject().put("at_ms",at).put("elapsed_ms",elapsed).put("event",event).put("detail",detail).put("thread",thread).put("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());append(row);}catch(Exception ignored){/* Diagnostics must not break notes. */}}});}catch(RejectedExecutionException full){/* Bounded queue: omit breadcrumb, never block UI. */}}
 private static File file(String name){return new File(app.getFilesDir(),name);}
 private static void append(JSONObject row)throws Exception {File current=file("diagnostics.jsonl");byte[] bytes=(row.toString()+"\n").getBytes("UTF-8");if(current.length()+bytes.length>LIMIT){File previous=file("diagnostics.previous.jsonl");if(previous.exists() && !previous.delete())return;if(!current.renameTo(previous))return;}try(FileOutputStream out=new FileOutputStream(current,true)){out.write(bytes);}}
 public static void failure(String event,Throwable error){if(!enabled)return;try{StringBuilder trace=new StringBuilder(error.getClass().getName());for(StackTraceElement frame:error.getStackTrace()){if(trace.length()>8000)break;trace.append("\n at ").append(frame);}record(event,trace.toString());}catch(Throwable ignored){}}
 public static void clear(){synchronized(LOCK){generation++;WRITER.getQueue().clear();file("diagnostics.jsonl").delete();file("diagnostics.previous.jsonl").delete();}}
 public static long bytes(){synchronized(LOCK){return file("diagnostics.jsonl").length()+file("diagnostics.previous.jsonl").length();}}
 public static void environment(String reason){if(!enabled)return;try{android.content.res.Configuration c=app.getResources().getConfiguration();android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();((android.app.ActivityManager)app.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(memory);JSONObject row=new JSONObject().put("reason",reason).put("sdk",Build.VERSION.SDK_INT).put("release",Build.VERSION.RELEASE).put("manufacturer",Build.MANUFACTURER).put("model",Build.MODEL).put("security_patch",Build.VERSION.SECURITY_PATCH).put("app_package",app.getPackageName()).put("timezone",java.util.TimeZone.getDefault().getID()).put("density_dpi",app.getResources().getDisplayMetrics().densityDpi).put("power_save",((PowerManager)app.getSystemService(Context.POWER_SERVICE)).isPowerSaveMode()).put("abis",java.util.Arrays.toString(Build.SUPPORTED_ABIS)).put("app_version",app.getPackageManager().getPackageInfo(app.getPackageName(),0).versionName).put("version_code",app.getPackageManager().getPackageInfo(app.getPackageName(),0).versionCode).put("font_scale",c.fontScale).put("orientation",c.orientation).put("night",c.uiMode & 48).put("width_dp",c.screenWidthDp).put("height_dp",c.screenHeightDp).put("locale",c.getLocales().toLanguageTags()).put("available_ram_bytes",memory.availMem).put("low_memory",memory.lowMemory).put("free_internal_bytes",app.getFilesDir().getUsableSpace()).put("pss_kib",Debug.getPss()).put("native_heap_bytes",Debug.getNativeHeapAllocatedSize()).put("microphone_granted",app.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==0).put("notifications_enabled",((android.app.NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled());record("environment",row.toString());}catch(Exception e){record("environment.failure",e.getClass().getSimpleName());}}
 private static void crash(Throwable error){synchronized(LOCK){if(!enabled || app==null)return;try{StringBuilder trace=new StringBuilder(error.getClass().getName());for(StackTraceElement frame:error.getStackTrace()){if(trace.length()>10000)break;trace.append("\n at ").append(frame);}append(new JSONObject().put("at_ms",System.currentTimeMillis()).put("event","uncaught.java").put("stack_no_messages",trace.toString()));}catch(Throwable ignored){}}}
 /** Snapshot is ordered behind prior breadcrumbs; caller streams off the UI thread. */
 public static void export(Context context,android.net.Uri uri,Runnable success,java.util.function.Consumer<Exception> failure){try{WRITER.execute(()->{
  try{ByteArrayOutputStream snapshot=new ByteArrayOutputStream();snapshot.write("MyNotes diagnostics v1 — app events only; no note bodies/audio/images/URI paths. Device context may identify your phone.\n".getBytes("UTF-8"));
   synchronized(LOCK){for(String name:new String[]{"diagnostics.previous.jsonl","diagnostics.jsonl"}){File f=file(name);if(f.exists())try(InputStream in=new FileInputStream(f)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)snapshot.write(buffer,0,n);}}}
   byte[] bytes=snapshot.toByteArray();EXPORTER.execute(()->{try{try(OutputStream out=context.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open destination");out.write(bytes);}success.run();}catch(Exception e){failure.accept(e);}});
  }catch(Exception e){failure.accept(e);}
 });}catch(RejectedExecutionException full){failure.accept(full);}}
}
